  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Naproxen, a close 2-arylpropionic acid analogue, has an absolute oral bioavailability of 99% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Flurbiprofen, another close analogue, is almost completely available (~92%) after oral administration in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Ketoprofen has an absolute oral bioavailability of at least 92% in humans compared with IV, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Ibuprofen is essentially 100% bioavailable after oral dosing compared with IV in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Pirprofen, a related propionic acid NSAID, shows high and uniform oral bioavailability in volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is carprofen, a 2-arylpropionic acid NSAID. All retrieved close structural analogues—naproxen, flurbiprofen, ketoprofen, ibuprofen, and pirprofen—show high absolute oral bioavailability in humans (70–100%), far above the 20% threshold. The shared propionic acid/carboxylate and lipophilic aromatic scaffold support transfer of this high-bioavailability phenotype to the query.",
  "evidence_gaps": [
    "No direct experimental record for carprofen itself was retrieved; the prediction relies on close structural analogues.",
    "Some analogue records are from pediatric or patient populations, though the majority are from healthy human adults."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

